script:
namespace eval ::SpiceGenTcl {
 namespace export Device
 oo::class create Device {method genSPICEString {} {return OK}}
}
set missing [catch {oo::class create ::Core {superclass Device}} message]
puts [list missing-import $missing $message]
catch {::Core destroy}
namespace import ::SpiceGenTcl::Device
set imported [catch {oo::class create ::Core {superclass Device}} message]
puts [list actual-import $imported $message]
if {!$imported} {set object [::Core new];puts [list inherited-call [$object genSPICEString]]}

rows.stdout:
